/**
 * Calibrate a multiroom group acoustically: each member's trim from its measured output latency (the owner's: every member plays a short chirp), measured by the speakers or scheduled for the owner's browser
 *
 * Every member plays a short chirp through its group playout, a few rounds (at the device's own level less 20 dB, never above it) and records its microphones, in memory only; the leader solves each member's output latency from the round trips (distance and microphones cancel), each arrival the median of its rounds. When every member was measured, its rounds agreeing within 0.5 ms, each member's trim becomes the negation of its offset and the configs are pushed again; only the trims and ultrasonic result tokens are stored. The owner's alone: refused while the group plays (409 playing), while its leader's volume does not hold yet (gated), with no member online (too_few) and in a voice turn. Takes up to about 30 s. boost plays the named members' chirps louder (up to 14 dB, still 6 dB under their own volume, which never changes). With mode listener, every member connected to the leader plays its chirps at its slots, the answer (code scheduled) comes at once with the schedule and a calibration id, and the owner's browser, recording where they listen, posts the arrivals it measured to apply-group-calibration.
 */
export const calibrateGroupMutation = (options?: Partial<Options<CalibrateGroupData>>): UseMutationOptions<CalibrateGroupResponse, CalibrateGroupError, Options<CalibrateGroupData>> => {
    const mutationOptions: UseMutationOptions<CalibrateGroupResponse, CalibrateGroupError, Options<CalibrateGroupData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await calibrateGroup({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Apply what the owner's browser heard of a listener calibration: each member's trim from its chirp's arrival
 *
 * The arrivals the owner's browser measured of a listener calibration's chirps (numbers only: no audio reaches the server). Each slot member's offset is its arrival less its round-0 slot; its trim becomes the negation of its offset less the slots' mean, stored and pushed as calibrate-group's. A slot member missing, not ok or spread past 0.5 ms gives code incomplete, a trim past 500 ms out_of_range; neither applies anything. The speakers' own measure of the same run, when their leader has one, is shown beside each member (micsCode, micsOffsetUs, pathUs), never applied. The id is used once, within 120 s of its scheduling: an unknown, used or expired one is refused 404 expired.
 */
export const applyGroupCalibrationMutation = (options?: Partial<Options<ApplyGroupCalibrationData>>): UseMutationOptions<ApplyGroupCalibrationResponse, ApplyGroupCalibrationError, Options<ApplyGroupCalibrationData>> => {
    const mutationOptions: UseMutationOptions<ApplyGroupCalibrationResponse, ApplyGroupCalibrationError, Options<ApplyGroupCalibrationData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await applyGroupCalibration({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

