/**
 * Test a provider instance with its module's cheapest free call
 *
 * Builds the instance afresh, never touching the one the runtime holds, and runs its module's cheapest call that costs nothing, within 10 s: ok, or a code (auth, unreachable, timeout, bad_response, unsupported, rate_limited, build_failed). A module with no such call answers unsupported. At most one test per instance per 5 s; past that the answer is 429 with Retry-After.
 */
export const testProviderMutation = (options?: Partial<Options<TestProviderData>>): UseMutationOptions<TestProviderResponse, TestProviderError, Options<TestProviderData>> => {
    const mutationOptions: UseMutationOptions<TestProviderResponse, TestProviderError, Options<TestProviderData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await testProvider({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

